"use client";
import { useRef } from "react";
import "./style.scss";

function Card() {
  const cardRef = useRef(null);
  const bgRef = useRef(null);

  const handleMouseMove = (e) => {
    const card = cardRef.current;
    const bg = bgRef.current;
    const rect = card.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width - 0.5) * 20; // max 10px left/right
    const y = ((e.clientY - rect.top) / rect.height - 0.5) * 20;

    bg.style.transform = `translate(${x}px, ${y}px)`;
  };

  const resetTransform = () => {
    bgRef.current.style.transform = "translate(0px, 0px)";
  };

  return (
    <div
      className="card"
      ref={cardRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={resetTransform}
    >
      <img
        ref={bgRef}
        className="card-background"
        src="https://www.fcgroningen.nl/wp-content/uploads/sites/7/2022/12/2-JEF09613-1536x864.jpg"
        alt=""
      />
      <div className="card-text">
        <h2>FCGroningen</h2>
        <p>Talent Group Groningen</p>
      </div>
      <div className="card-spacing">
        <button className="card-button">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 384 512"
          >
            <path d="M214.6 41.4c-12.5-12.5-32.8-12.5-45.3 0l-160 160c-12.5 12.5-12.5 32.8 0 45.3s32.8 12.5 45.3 0L160 141.2 160 448c0 17.7 14.3 32 32 32s32-14.3 32-32l0-306.7L329.4 246.6c12.5 12.5 32.8 12.5 45.3 0s12.5-32.8 0-45.3l-160-160z" />
          </svg>
        </button>
      </div>
      <div className="card-gradient"></div>
    </div>
  );
}

export { Card };
